namespace sv_00eb60e128eb4d1f9cb519b471164ec1.Client.Auth;

public sealed class UserInfo
{
    public required string Email { get; init; }
    public required string[] Roles { get; init; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_00eb60e128eb4d1f9cb519b471164ec1.Client.Auth;

/// <summary>
/// On WebAssembly, reads the serialized user info that the server persisted
/// into <see cref="PersistentComponentState"/> so the identity survives the
/// Server → WASM handoff.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authState;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            _authState = Task.FromResult(new AuthenticationState(CreatePrincipal(userInfo)));
        }
        else
        {
            _authState = _unauthenticated;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;

    private static ClaimsPrincipal CreatePrincipal(UserInfo user)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, user.Email),
            new(ClaimTypes.Email, user.Email),
        };

        foreach (var role in user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: nameof(PersistentAuthenticationStateProvider));
        return new ClaimsPrincipal(identity);
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_00eb60e128eb4d1f9cb519b471164ec1.Auth;

/// <summary>
/// Always returns a logged-in user "bob@example.com" with roles "User" and "Editor".
/// </summary>
public sealed class HardcodedAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _state;

    static HardcodedAuthenticationStateProvider()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        var principal = new ClaimsPrincipal(identity);
        _state = Task.FromResult(new AuthenticationState(principal));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _state;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_00eb60e128eb4d1f9cb519b471164ec1.Client.Auth;

namespace sv_00eb60e128eb4d1f9cb519b471164ec1.Auth;

/// <summary>
/// Wraps the <see cref="HardcodedAuthenticationStateProvider"/> on the server side
/// and serializes the user's claims into <see cref="PersistentComponentState"/> so
/// that the client-side WASM runtime can pick them up after the handoff.
/// </summary>
public sealed class PersistingServerAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly AuthenticationStateProvider _inner;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public PersistingServerAuthenticationStateProvider(
        PersistentComponentState persistentState,
        HardcodedAuthenticationStateProvider inner)
    {
        _persistentState = persistentState;
        _inner = inner;
        AuthenticationStateChanged += OnAuthenticationStateChanged;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => _inner.GetAuthenticationStateAsync();

    /// <summary>
    /// Required by <see cref="IHostEnvironmentAuthenticationStateProvider"/>.
    /// The framework calls this to push the host-level auth state.
    /// </summary>
    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authStateTask = authenticationStateTask;
        NotifyAuthenticationStateChanged(authenticationStateTask);
    }

    private void OnAuthenticationStateChanged(Task<AuthenticationState> task) => _authStateTask = task;

    private async Task OnPersistingAsync()
    {
        var authState = await (_authStateTask ?? GetAuthenticationStateAsync());
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var email = principal.FindFirst(ClaimTypes.Email)?.Value ?? principal.Identity.Name!;
            var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

            _persistentState.PersistAsJson(nameof(UserInfo), new UserInfo
            {
                Email = email,
                Roles = roles,
            });
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
        AuthenticationStateChanged -= OnAuthenticationStateChanged;
    }
}

